package v1alpha2

import (
	"testing"

	"github.com/stretchr/testify/require"
	"k8s.io/apimachinery/pkg/api/resource"
)

func TestValidateRuntime(t *testing.T) {
	require.NoError(t, (&SandboxPoolSpec{Runtime: RuntimeKataFc}).ValidateRuntime())
	require.NoError(t, (&SandboxPoolSpec{Runtime: RuntimeKataDragonball}).ValidateRuntime())
	require.NoError(t, (&SandboxPoolSpec{Runtime: RuntimeFirecracker}).ValidateRuntime())
	require.Error(t, (&SandboxPoolSpec{}).ValidateRuntime())
	require.Error(t, (&SandboxPoolSpec{Runtime: RuntimeName("boxlite")}).ValidateRuntime())
	require.Error(t, (&SandboxPoolSpec{Runtime: RuntimeName("unknown")}).ValidateRuntime())
}

func TestValidateSandboxPoolUpdate(t *testing.T) {
	base := SandboxPoolSpec{
		Runtime: RuntimeContainer,
		SandboxResources: SandboxResourceProfile{
			CPU:    resource.MustParse("1"),
			Memory: resource.MustParse("1Gi"),
			PIDs:   256,
		},
	}

	same := *base.DeepCopy()
	require.NoError(t, ValidateSandboxPoolUpdate(&base, &same))

	runtimeChanged := *base.DeepCopy()
	runtimeChanged.Runtime = RuntimeGVisor
	require.ErrorIs(t, ValidateSandboxPoolUpdate(&base, &runtimeChanged), ErrRuntimeImmutable)

	resourcesChanged := *base.DeepCopy()
	resourcesChanged.SandboxResources.Memory = resource.MustParse("2Gi")
	require.ErrorIs(t, ValidateSandboxPoolUpdate(&base, &resourcesChanged), ErrResourcesImmutable)
}

func TestValidateActionHandlersAndRejectRemoval(t *testing.T) {
	handler := ActionHandler{Name: "egress", TargetHTTPPort: 18080}
	base := SandboxPoolSpec{Runtime: RuntimeContainer, ActionHandlers: []ActionHandler{handler}}
	require.NoError(t, base.ValidateActionHandlers())

	duplicate := base
	duplicate.ActionHandlers = append(duplicate.ActionHandlers, handler)
	require.ErrorIs(t, duplicate.ValidateActionHandlers(), ErrActionHandlersInvalid)

	for _, port := range []int32{5758, 5780, 9093} {
		reserved := base
		reserved.ActionHandlers = append([]ActionHandler(nil), base.ActionHandlers...)
		reserved.ActionHandlers[0].TargetHTTPPort = port
		require.ErrorIs(t, reserved.ValidateActionHandlers(), ErrActionHandlersInvalid)
	}

	removed := base
	removed.ActionHandlers = nil
	// Fill the otherwise required immutable fields equally; Action removal is
	// the only relevant difference.
	require.ErrorIs(t, ValidateSandboxPoolUpdate(&base, &removed), ErrActionHandlersRemoved)
}

func TestGenerationAndAssignmentValidation(t *testing.T) {
	require.Equal(t, int64(1), NextInstanceGeneration(0))
	require.Equal(t, int64(2), NextInstanceGeneration(1))

	placement := &PlacementStatus{
		FastletName: "fastlet-1", FastletPodUID: "pod-uid", Attempt: 1,
	}
	require.NoError(t, placement.Validate())
	placement.Attempt = 0
	require.Error(t, placement.Validate())
}

func TestValidateInfraComponents(t *testing.T) {
	valid := SandboxPoolSpec{InfraComponents: []InfraComponent{{
		Name: "execd",
		Artifact: &InfraArtifact{
			Source: InfraArtifactSource{Image: &InfraArtifactImage{
				Reference: "ghcr.io/opensandbox/execd@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
			}},
			Mappings: []InfraArtifactMapping{{
				SourcePath: "/usr/local/bin/execd", TargetPath: "/.fast/components/execd/execd",
			}},
		},
		Process: InfraProcess{
			Command:     []string{"/.fast/components/execd/execd", "--port", "44772"},
			HealthCheck: InfraHealthCheck{HTTPGet: &InfraHTTPGet{Path: "/ping"}, TimeoutSeconds: 10},
		},
		Endpoint: InfraEndpoint{Protocol: "HTTP", Port: 44772},
	}}}
	require.NoError(t, valid.ValidateInfraComponents())

	duplicatePort := *valid.DeepCopy()
	second := duplicatePort.InfraComponents[0]
	second.Name = "envd"
	second.Artifact.Mappings[0].TargetPath = "/.fast/components/envd/envd"
	duplicatePort.InfraComponents = append(duplicatePort.InfraComponents, second)
	require.ErrorIs(t, duplicatePort.ValidateInfraComponents(), ErrInfraComponentsInvalid)

	escapedTarget := *valid.DeepCopy()
	escapedTarget.InfraComponents[0].Artifact.Mappings[0].TargetPath = "/usr/local/bin/execd"
	require.ErrorIs(t, escapedTarget.ValidateInfraComponents(), ErrInfraComponentsInvalid)

	tokenEnv := *valid.DeepCopy()
	tokenEnv.InfraComponents[0].Process.Env = map[string]string{"FAST_SANDBOX_TOKEN": "bad"}
	require.ErrorIs(t, tokenEnv.ValidateInfraComponents(), ErrInfraComponentsInvalid)
}

func TestValidateHostProcessInfraComponent(t *testing.T) {
	hostProcess := SandboxPoolSpec{InfraComponents: []InfraComponent{{
		Name:     "egress",
		Delivery: InfraDeliveryHostProcess,
		Process: InfraProcess{
			Command:     []string{"/bin/egress"},
			HealthCheck: InfraHealthCheck{TCPConnect: &InfraTCPConnect{}, TimeoutSeconds: 10},
		},
		Endpoint: InfraEndpoint{Protocol: "HTTP", Port: 18080},
	}}}
	require.NoError(t, hostProcess.ValidateInfraComponents())

	withArtifact := *hostProcess.DeepCopy()
	withArtifact.InfraComponents[0].Artifact = &InfraArtifact{
		Source: InfraArtifactSource{Image: &InfraArtifactImage{
			Reference: "registry.example/egress@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
		}},
		Mappings: []InfraArtifactMapping{{SourcePath: "/egress", TargetPath: "/.fast/components/egress/egress"}},
	}
	require.ErrorIs(t, withArtifact.ValidateInfraComponents(), ErrInfraComponentsInvalid)

	unsupportedDelivery := *hostProcess.DeepCopy()
	unsupportedDelivery.InfraComponents[0].Delivery = "bind-mount"
	require.ErrorIs(t, unsupportedDelivery.ValidateInfraComponents(), ErrInfraComponentsInvalid)

	missingArtifact := SandboxPoolSpec{InfraComponents: []InfraComponent{{
		Name: "execd",
		Process: InfraProcess{
			Command:     []string{"/bin/execd"},
			HealthCheck: InfraHealthCheck{TCPConnect: &InfraTCPConnect{}, TimeoutSeconds: 10},
		},
		Endpoint: InfraEndpoint{Protocol: "HTTP", Port: 44772},
	}}}
	require.ErrorIs(t, missingArtifact.ValidateInfraComponents(), ErrInfraComponentsInvalid)
}

func TestSandboxResourceProfileHashIsCanonical(t *testing.T) {
	a := SandboxResourceProfile{CPU: resource.MustParse("1"), Memory: resource.MustParse("1024Mi"), PIDs: 256}
	b := SandboxResourceProfile{CPU: resource.MustParse("1000m"), Memory: resource.MustParse("1Gi"), PIDs: 256}
	require.Equal(t, a.Hash(), b.Hash())
	b.PIDs++
	require.NotEqual(t, a.Hash(), b.Hash())
}

func TestValidateSandboxResourceProfile(t *testing.T) {
	valid := SandboxResourceProfile{CPU: resource.MustParse("500m"), Memory: resource.MustParse("256Mi"), PIDs: 128}
	require.NoError(t, ValidateSandboxResourceProfile(valid))
	require.ErrorIs(t, ValidateSandboxResourceProfile(SandboxResourceProfile{}), ErrInvalidSandboxResourceProfile)
	require.ErrorIs(t, ValidateSandboxResourceProfile(SandboxResourceProfile{
		CPU: resource.MustParse("1"),
	}), ErrInvalidSandboxResourceProfile)
	require.ErrorIs(t, ValidateSandboxResourceProfile(SandboxResourceProfile{
		CPU: resource.MustParse("1m"), Memory: resource.MustParse("256Mi"), PIDs: 128,
	}), ErrInvalidSandboxResourceProfile)
}

package firecracker

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"fast-sandbox/internal/registryconfig"
	"fast-sandbox/internal/runtime/firecracker/agent"
)

// TestAgentPullFeedsDriverCache wires the runtime-agent pull layer to the
// driver's existing cache consumer: after PullImage, the restore path
// (resolveRootfsImage) resolves the pulled artifact without any driver
// change, and the per-build digest namespace and file mapping
// (rootfs.ext4 -> rootfs.img) match the published layout.
func TestAgentPullFeedsDriverCache(t *testing.T) {
	const (
		image       = "registry.example.com/sandbox:v1.0.21"
		bucket      = "sandbox-images"
		storePrefix = "publish"
	)
	artifacts := map[string][]byte{
		"rootfs.ext4":  []byte("rootfs-content"),
		"vmstate.snap": []byte("vmstate-content"),
		"memory.snap":  []byte("memory-content"),
	}
	files := map[string]any{}
	for name, content := range artifacts {
		files[name] = map[string]any{
			"sha256":    sha256HexTest(content),
			"sizeBytes": len(content),
		}
	}
	manifestBytes, err := json.Marshal(map[string]any{"schemaVersion": 1, "runtime": "firecracker", "files": files})
	require.NoError(t, err)
	digest16 := sha256HexTest(manifestBytes)[:16]

	objects := map[string][]byte{
		digest16 + "/manifest.json": manifestBytes,
	}
	for name, content := range artifacts {
		objects[digest16+"/"+name] = content
	}
	indexBytes, err := json.Marshal(map[string]string{
		"image":          image,
		"manifestRef":    "s3://" + bucket + "/" + storePrefix + "/" + digest16 + "/manifest.json",
		"artifactDigest": sha256HexTest(manifestBytes),
		"updatedAt":      "2026-08-27T00:00:00Z",
	})
	require.NoError(t, err)
	objects["index/"+imageKey(image)+".json"] = indexBytes

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		content, ok := objects[strings.TrimPrefix(r.URL.Path, "/"+bucket+"/"+storePrefix+"/")]
		if !ok {
			http.NotFound(w, nil)
			return
		}
		_, _ = w.Write(content)
	}))
	defer server.Close()

	client, err := agent.NewClient("s3://"+bucket+"/"+storePrefix,
		registryconfig.Credential{Host: server.URL, Username: "ak", Password: "sk"})
	require.NoError(t, err)

	stateRoot := t.TempDir()
	require.NoError(t, client.PullImage(context.Background(), stateRoot, image))

	// The driver's existing restore consumer resolves the pulled rootfs
	// image under the shared cache layout.
	resolved, err := resolveRootfsImage(stateRoot, image)
	require.NoError(t, err)
	expected, err := imageCachePath(stateRoot, image)
	require.NoError(t, err)
	require.Equal(t, expected, resolved)
	content, err := os.ReadFile(resolved)
	require.NoError(t, err)
	require.Equal(t, artifacts["rootfs.ext4"], content)

	// A second pull is a no-op for the store, and the driver's idempotent
	// PullImage also sees the image as ready.
	require.NoError(t, client.PullImage(context.Background(), stateRoot, image))
	driver := &Driver{config: firecrackerConfigForTest(t, stateRoot)}
	require.NoError(t, driver.PullImage(context.Background(), image))
}

func sha256HexTest(payload []byte) string {
	digest := sha256.Sum256(payload)
	return hex.EncodeToString(digest[:])
}

package agent

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

// TestFileMatchesSizeFastPath verifies the stat-first size check: a file
// with the wrong size is rejected without reading (the fast path), a file
// with the right size but wrong content is rejected by the digest, and an
// exact match passes.
func TestFileMatchesSizeFastPath(t *testing.T) {
	content := bytes.Repeat([]byte{0xab}, 1<<20)
	file := nativeFile{publish: "rootfs.ext4", cache: "rootfs.img", sha256: sha256Hex(content), sizeBytes: int64(len(content))}
	path := filepath.Join(t.TempDir(), "rootfs.img")

	// Missing file.
	match, err := fileMatches(path, file)
	require.ErrorIs(t, err, os.ErrNotExist)
	require.False(t, match)

	// Wrong size: rejected by stat, no content read needed.
	require.NoError(t, os.WriteFile(path, []byte("tiny"), cacheFileMode))
	match, err = fileMatches(path, file)
	require.NoError(t, err)
	require.False(t, match)

	// Right size, wrong content: caught by the digest.
	wrong := bytes.Repeat([]byte{0x00}, len(content))
	require.NoError(t, os.WriteFile(path, wrong, cacheFileMode))
	match, err = fileMatches(path, file)
	require.NoError(t, err)
	require.False(t, match)

	// Exact match.
	require.NoError(t, os.WriteFile(path, content, cacheFileMode))
	match, err = fileMatches(path, file)
	require.NoError(t, err)
	require.True(t, match)
}

// TestCacheComplete checks the committed-pull predicate: any missing,
// resized, or corrupted file (or a missing manifest) invalidates the cache.
func TestCacheComplete(t *testing.T) {
	artifacts := map[string][]byte{
		"rootfs.ext4":  bytes.Repeat([]byte{0xab}, 1<<16),
		"vmstate.snap": []byte("vmstate"),
		"memory.snap":  []byte("memory"),
	}
	manifestPayload := testManifest(artifacts)
	document, err := parseManifest(manifestPayload)
	require.NoError(t, err)
	files, err := document.nativeFiles()
	require.NoError(t, err)

	dir := t.TempDir()
	require.NoError(t, os.MkdirAll(dir, cacheDirMode))

	// No manifest: not complete.
	complete, err := cacheComplete(dir)
	require.NoError(t, err)
	require.False(t, complete)

	// Manifest but no files: not complete.
	require.NoError(t, os.WriteFile(filepath.Join(dir, manifestName), manifestPayload, cacheFileMode))
	complete, err = cacheComplete(dir)
	require.NoError(t, err)
	require.False(t, complete)

	// A file with the wrong size: not complete (fast path).
	for _, file := range files[:1] {
		require.NoError(t, os.WriteFile(filepath.Join(dir, file.cache), []byte("tiny"), cacheFileMode))
	}
	complete, err = cacheComplete(dir)
	require.NoError(t, err)
	require.False(t, complete)

	// All files exact: complete.
	for _, file := range files {
		require.NoError(t, os.WriteFile(filepath.Join(dir, file.cache), artifacts[file.publish], cacheFileMode))
	}
	complete, err = cacheComplete(dir)
	require.NoError(t, err)
	require.True(t, complete)

	// Any single corrupt file breaks the commit.
	require.NoError(t, os.WriteFile(filepath.Join(dir, files[1].cache), []byte("tampered"), cacheFileMode))
	complete, err = cacheComplete(dir)
	require.NoError(t, err)
	require.False(t, complete)
}

package observability

import (
	"context"
	"errors"
	"os"
	"strings"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
)

type Shutdown func(context.Context) error

// Configure installs an OTLP/gRPC trace provider only when an OTLP traces
// endpoint is explicitly configured. The exporter follows the standard
// OTEL_EXPORTER_OTLP_* environment variables. Without an endpoint, tracing is
// a no-op while W3C context propagation remains active.
func Configure(ctx context.Context, defaultServiceName string) (Shutdown, error) {
	if !tracingEnabled() {
		return func(context.Context) error { return nil }, nil
	}
	serviceName := strings.TrimSpace(os.Getenv("OTEL_SERVICE_NAME"))
	if serviceName == "" {
		serviceName = defaultServiceName
	}
	if serviceName == "" {
		return nil, errors.New("OpenTelemetry service name is required")
	}
	exporter, err := otlptracegrpc.New(ctx)
	if err != nil {
		return nil, err
	}
	serviceResource, err := resource.New(ctx,
		resource.WithFromEnv(),
		resource.WithTelemetrySDK(),
		resource.WithAttributes(attribute.String("service.name", serviceName)),
	)
	if err != nil {
		return nil, err
	}
	provider := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exporter),
		sdktrace.WithResource(serviceResource),
	)
	otel.SetTracerProvider(provider)
	return provider.Shutdown, nil
}

func tracingEnabled() bool {
	if strings.EqualFold(strings.TrimSpace(os.Getenv("OTEL_SDK_DISABLED")), "true") {
		return false
	}
	return strings.TrimSpace(os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT")) != "" ||
		strings.TrimSpace(os.Getenv("OTEL_EXPORTER_OTLP_TRACES_ENDPOINT")) != ""
}

// sandbox-action-fixture is a small conforming Handler used only by the
// Quick Start demo and Sandbox Actions E2E suite.
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"

	actionapi "fast-sandbox/internal/protocol/action"
	"fast-sandbox/pkg/util/idgen"
)

type fixture struct {
	mu               sync.Mutex
	instanceID       string
	states           map[string]bindingState
	seen             map[string]struct{}
	removeDelayPorts map[string]struct{}
}

type bindingState struct {
	input string
	hooks map[actionapi.LifecycleHook]int64
}

func main() {
	instanceID, err := idgen.GenerateRequestID()
	if err != nil {
		log.Fatal(err)
	}
	handler := &fixture{
		instanceID: instanceID, states: make(map[string]bindingState), seen: make(map[string]struct{}),
		removeDelayPorts: stringSet(os.Getenv("SANDBOX_ACTION_FIXTURE_REMOVE_DELAY_PORTS")),
	}
	addresses := strings.Split(os.Getenv("SANDBOX_ACTION_FIXTURE_ADDRESSES"), ",")
	if len(addresses) == 1 && addresses[0] == "" {
		addresses = []string{"127.0.0.1:18080"}
	}
	for _, configuredAddress := range addresses {
		address := strings.TrimSpace(configuredAddress)
		mux := http.NewServeMux()
		mux.HandleFunc("/_fastlet/v1/actions/status", handler.status)
		mux.HandleFunc("/_fastlet/v1/actions", func(writer http.ResponseWriter, request *http.Request) {
			handler.invoke(address, writer, request)
		})
		go func() {
			log.Printf("sandbox Action fixture listening on %s instance=%s", address, instanceID)
			if err := http.ListenAndServe(address, mux); err != nil {
				log.Fatal(err)
			}
		}()
	}
	select {}
}

func (f *fixture) status(writer http.ResponseWriter, request *http.Request) {
	if request.Method != http.MethodGet {
		http.Error(writer, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	writeJSON(writer, http.StatusOK, actionapi.HandlerStatus{APIVersion: actionapi.APIVersion, Ready: true, InstanceID: f.instanceID})
}

func (f *fixture) invoke(address string, writer http.ResponseWriter, request *http.Request) {
	if request.Method != http.MethodPost {
		http.Error(writer, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var invocation actionapi.Request
	decoder := json.NewDecoder(http.MaxBytesReader(writer, request.Body, 128<<10))
	if err := decoder.Decode(&invocation); err != nil {
		http.Error(writer, err.Error(), http.StatusBadRequest)
		return
	}
	if invocation.APIVersion != actionapi.APIVersion || invocation.InvocationID == "" || invocation.Sandbox.UID == "" || invocation.Revision.AttachmentID == "" {
		http.Error(writer, "invalid Action envelope", http.StatusBadRequest)
		return
	}
	targetPort := address[strings.LastIndex(address, ":")+1:]
	if invocation.Operation == actionapi.OperationRemoveBinding {
		if _, delayed := f.removeDelayPorts[targetPort]; delayed {
			// The key=value fields of the request log lines (here, below, and
			// in logInvocation) are asserted by the Sandbox Actions E2E suite
			// (sandbox_actions_test.go greps the fixture Pod logs); keep the
			// format stable or update the suite with it.
			log.Printf("targetPort=%s operation=%s sandboxUid=%s invocationId=%s injectedRemoveDelay=true", targetPort, invocation.Operation, invocation.Sandbox.UID, invocation.InvocationID)
			elapsed, cancelled := waitForCancellation(request.Context())
			log.Printf("targetPort=%s operation=%s sandboxUid=%s invocationId=%s injectedRemoveDelayComplete=true cancelled=%t elapsedMillis=%d", targetPort, invocation.Operation, invocation.Sandbox.UID, invocation.InvocationID, cancelled, elapsed.Milliseconds())
			return
		}
	}
	key := address + "/" + invocation.Sandbox.UID
	f.mu.Lock()
	if _, duplicate := f.seen[invocation.InvocationID]; duplicate {
		f.mu.Unlock()
		logInvocation(address, invocation, true)
		writer.WriteHeader(http.StatusOK)
		return
	}
	switch invocation.Operation {
	case actionapi.OperationSetBinding:
		if invocation.Binding == nil {
			f.mu.Unlock()
			http.Error(writer, "SET_BINDING requires binding payload", http.StatusBadRequest)
			return
		}
		if invocation.Binding.Input == nil {
			delete(f.states, key)
		} else {
			state := f.states[key]
			state.input = *invocation.Binding.Input
			if state.hooks == nil {
				state.hooks = make(map[actionapi.LifecycleHook]int64)
			}
			f.states[key] = state
		}
	case actionapi.OperationLifecycleHook:
		if invocation.Hook == nil {
			f.mu.Unlock()
			http.Error(writer, "LIFECYCLE_HOOK requires hook payload", http.StatusBadRequest)
			return
		}
		state, found := f.states[key]
		if !found {
			f.mu.Unlock()
			http.Error(writer, "Binding must be set before Hook", http.StatusConflict)
			return
		}
		if state.hooks == nil {
			state.hooks = make(map[actionapi.LifecycleHook]int64)
		}
		state.hooks[invocation.Hook.Name] = invocation.Hook.Sequence
		f.states[key] = state
	case actionapi.OperationRemoveBinding:
		if invocation.Binding != nil || invocation.Hook != nil {
			f.mu.Unlock()
			http.Error(writer, "REMOVE_BINDING does not accept a payload", http.StatusBadRequest)
			return
		}
		delete(f.states, key)
	default:
		f.mu.Unlock()
		http.Error(writer, "unsupported operation", http.StatusBadRequest)
		return
	}
	f.seen[invocation.InvocationID] = struct{}{}
	f.mu.Unlock()
	logInvocation(address, invocation, false)
	writer.WriteHeader(http.StatusOK)
}

func logInvocation(address string, invocation actionapi.Request, duplicate bool) {
	targetPort := address[strings.LastIndex(address, ":")+1:]
	input := "<none>"
	if invocation.Binding != nil {
		if invocation.Binding.Input == nil {
			input = "<nil>"
		} else {
			input = fmt.Sprintf("%q", *invocation.Binding.Input)
		}
	}
	hook := ""
	if invocation.Hook != nil {
		hook = fmt.Sprintf("%s/%d", invocation.Hook.Name, invocation.Hook.Sequence)
	}
	// Format asserted by the Actions E2E suite; see the note in invoke.
	log.Printf("targetPort=%s operation=%s input=%s hook=%s sandboxUid=%s generation=%d attachmentId=%s invocationId=%s duplicate=%t", targetPort, invocation.Operation, input, hook, invocation.Sandbox.UID, invocation.Revision.SpecGeneration, invocation.Revision.AttachmentID, invocation.InvocationID, duplicate)
}

func stringSet(value string) map[string]struct{} {
	result := make(map[string]struct{})
	for _, item := range strings.Split(value, ",") {
		if item = strings.TrimSpace(item); item != "" {
			result[item] = struct{}{}
		}
	}
	return result
}

func waitForCancellation(ctx context.Context) (time.Duration, bool) {
	started := time.Now()
	select {
	case <-ctx.Done():
		return time.Since(started), true
	case <-time.After(30 * time.Second):
		return time.Since(started), false
	}
}

func writeJSON(writer http.ResponseWriter, status int, value any) {
	writer.Header().Set("Content-Type", "application/json")
	writer.WriteHeader(status)
	if err := json.NewEncoder(writer).Encode(value); err != nil {
		log.Print(fmt.Errorf("encode response: %w", err))
	}
}

package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeCredentialFile(t *testing.T, dir, key, value string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, key), []byte(value), 0o600); err != nil {
		t.Fatalf("write %s: %v", key, err)
	}
}

func TestLoadPublishCredentialsReadsMountedKeys(t *testing.T) {
	dir := t.TempDir()
	writeCredentialFile(t, dir, publishSecretKeyID, "AKID\n")
	writeCredentialFile(t, dir, publishSecretKeySecret, " SKEY ")
	writeCredentialFile(t, dir, publishSecretKeyPoint, "http://minio:9000")
	writeCredentialFile(t, dir, publishSecretKeyRegion, "cn-hangzhou\n")

	credentials, err := loadPublishCredentials(dir)
	if err != nil {
		t.Fatalf("load credentials: %v", err)
