	t.Setenv("FAST_SANDBOX_VAULT_HANDLER", "")
	require.Equal(t, "egress", VaultHandlerFromEnv())
	t.Setenv("FAST_SANDBOX_VAULT_HANDLER", "secret-vault")
	require.Equal(t, "secret-vault", VaultHandlerFromEnv())
}

package action

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
